WITH accounts_by_customer AS (SELECT customer_id, SUM(CASE WHEN status = 'FROZEN' THEN balance ELSE 0 END) frozen_balance, ROUND(AVG(balance), 2) avg_balance FROM accounts WHERE balance >= 48000 GROUP BY customer_id) SELECT c.id, c.age, c.credit_limit, abc.frozen_balance, abc.avg_balance FROM customers c INNER JOIN accounts_by_customer abc ON c.id = abc.customer_id ORDER BY frozen_balance;
